TR_ONES = ["", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]
TR_TENS = ["", "on", "yirmi", "otuz", "kırk", "elli", "altmış", "yetmiş", "seksen", "doksan"]
TR_MONTHS = ["", "Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"]
TR_DIG = ["sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]

def tr_under_1000(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else TR_ONES[h] + " ") + "yüz")
    if t:
        s.append(TR_TENS[t])
    if o:
        s.append(TR_ONES[o])
    return " ".join(s)

def tr_words(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for div, name in ((10**9, "milyar"), (10**6, "milyon"), (1000, "bin")):
        q, n = divmod(n, div)
        if q:
            if div == 1000 and q == 1:
                parts.append("bin")
            else:
                parts.append(tr_under_1000(q) + " " + name)
    if n:
        parts.append(tr_under_1000(n))
    return " ".join(parts)

def tr_money(x, cur):
    x = round(float(x) + 1e-9, 2)
    whole = int(x)
    frac = int(round((x - whole) * 100))
    unit = {"TL": "lira", "USD": "dolar", "EUR": "euro", "GBP": "sterlin"}[cur]
    sub = {"TL": "kuruş", "USD": "sent", "EUR": "sent", "GBP": "peni"}[cur]
    if cur == "TL" and not frac:
        return tr_words(whole) + " Türk Lirası"
    s = tr_words(whole) + " " + unit
    if frac:
        s += " " + tr_words(frac) + " " + sub
    return s

TR_SUF = {"Lirası": "'dır", "lira": "'dır", "kuruş": "'tur", "dolar": "'dır", "sent": "'tir", "euro": "'dur", "sterlin": "'dir", "peni": "'dir"}

def sfx(s):
    return s + TR_SUF.get(s.split(" ")[-1], "'dir")

def tr_date(s):
    try:
        d, m, y = [int(p) for p in str(s).split(".")]
        return "%d %s %d" % (d, TR_MONTHS[m], y)
    except Exception:
        return str(s)

def date_sfx(s):
    try:
        y = int(str(s).split(".")[2])
    except Exception:
        return "'dir"
    last = {1: "'dir", 2: "'dir", 3: "'tür", 4: "'tür", 5: "'tir", 6: "'dır", 7: "'dir", 8: "'dir", 9: "'dur"}
    if y % 10:
        return last[y % 10]
    return {1: "'dur", 2: "'dir", 3: "'dur", 4: "'tır", 5: "'dir", 6: "'tır", 7: "'tir", 8: "'dir", 9: "'dır", 0: "'dir"}[(y // 10) % 10]

def tr_iso(s):
    try:
        d, m, y = [int(p) for p in str(s).split(".")]
        return "%04d-%02d-%02d" % (y, m, d)
    except Exception:
        return ""

def tr_digits(s):
    return " ".join(TR_DIG[int(c)] for c in str(s) if c.isdigit())

def tr_num(v):
    try:
        return float(v)
    except Exception:
        return 0.0

CUR_NAME = {"TL": "Türk Lirası", "USD": "Dolar", "EUR": "Euro", "GBP": "İngiliz Sterlini"}

def tr_join(names):
    if len(names) == 1:
        return names[0]
    return ", ".join(names[:-1]) + " ve " + names[-1]

def build_reading(b, today_iso, product, last4):
    """b: the data object of cards.balance. Returns the full Turkish reading and a few facts."""
    intro_name = ("Sonu " + tr_digits(last4) + " ile biten " + product) if product else ("Sonu " + tr_digits(last4) + " ile biten")
    st, due = b.get("statementDate", ""), b.get("lastPayDate", "")
    st_iso, due_iso = tr_iso(st), tr_iso(due)
    blocks = {"TL": b.get("debtTL"), "USD": b.get("debtUSD"), "EUR": b.get("debtEUR"), "GBP": b.get("debtGBP")}
    out = []
    notes = []
    if st_iso and today_iso == st_iso:
        notes.append("Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.")
    top_status = str(b.get("statementPaymentStatus", ""))
    if top_status == "NO_DEBT" or not st:
        tl = blocks.get("TL") or {}
        total = tr_num(tl.get("totalDebt"))
        s = intro_name + " kartınızın " + tr_date(st) + " tarihli ekstresinden borcunuz bulunmamaktadır."
        if not st:
            s = intro_name + " kartınıza ait kesilmiş bir ekstre bulunmadığı için ekstre borcunuz bulunmamaktadır."
        if total > 0:
            s += " Gelecek dönemler dahil toplam borcunuz " + sfx(tr_money(total, "TL")) + "."
        if due and st:
            s += " Son ödeme tarihiniz " + tr_date(due) + " olacaktır."
        return " ".join(notes + [s]), True
    first = [True]
    def opener():
        if first[0]:
            first[0] = False
            return intro_name + " kartınıza ait " + tr_date(st) + " tarihinde kesilen ekstre "
        return ""
    clear = []
    tl = blocks.get("TL")
    if isinstance(tl, dict) and tl:
        sd, mp, rd, rmp = (tr_num(tl.get(k)) for k in ("statementDebt", "minPayment", "remainingDebt", "remainingMinPayment"))
        transfers = [CUR_NAME[c] for c in ("USD", "EUR", "GBP") if isinstance(blocks.get(c), dict) and tr_num(blocks[c].get("transferAmount")) > 0]
        if rd <= 0:
            clear.append("Türk Lirası")
        else:
            if transfers:
                out.append(tr_join(transfers) + " borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.")
            o = opener()
            lead = (o + "Türk Lirası borcunuz ") if o else "Türk Lirası borcunuz "
            X, Z, Y, T = tr_money(sd, "TL"), tr_money(mp, "TL"), tr_money(rd, "TL"), tr_money(rmp, "TL")
            if rmp <= 0:
                out.append(lead + X + ", kalan toplam borcunuz " + sfx(Y) + ". Minimum ödemenizi yaptığınız için teşekkür ederiz.")
            elif rmp >= mp:
                out.append(lead + X + ", ödenmesi gereken minimum tutar " + sfx(Z) + ".")
            else:
                out.append(lead + X + ", ödenmesi gereken minimum tutar " + Z + ", kalan toplam borcunuz " + Y + ", kalan minimum ödeme tutarınız " + sfx(T) + ".")
    for c in ("USD", "EUR", "GBP"):
        blk = blocks.get(c)
        if not isinstance(blk, dict) or not blk:
            continue
        sd, mp, rd = (tr_num(blk.get(k)) for k in ("statementDebt", "minPayment", "remainingDebt"))
        if rd <= 0 and sd <= 0:
            clear.append(CUR_NAME[c])
            continue
        if rd <= 0:
            clear.append(CUR_NAME[c])
            continue
        o = opener()
        out.append(o + CUR_NAME[c] + " borcunuz " + tr_money(sd, c) + ", kalan toplam borcunuz " + tr_money(rd, c) + ", ödenmesi gereken minimum tutar " + sfx(tr_money(mp, c)) + ".")
    if not out:
        s = intro_name + " kartınızın " + tr_date(st) + " tarihli ekstresinden borcunuz bulunmamaktadır."
        return " ".join(notes + [s] + ([("Son ödeme tarihiniz " + tr_date(due) + " olacaktır.")] if due else [])), True
    if clear:
        out.append(tr_join(clear) + " borcunuz bulunmamaktadır.")
    if due_iso and today_iso > due_iso:
        out.append("Son ödeme tarihiniz " + tr_date(due) + " geçmiştir.")
        tlb = blocks.get("TL") or {}
        if str(b.get("automaticPaymentFlag")) == "Y" and tr_num(tlb.get("remainAutomaticPaymentAmount")) > 0:
            out.append("Otomatik ödeme talimatınızdan alınacak kalan tutar " + sfx(tr_money(tlb.get("remainAutomaticPaymentAmount"), "TL")) + ".")
        if tr_num(tlb.get("totalDebt")) > 0:
            out.append("Toplam borcunuz " + sfx(tr_money(tlb.get("totalDebt"), "TL")) + ".")
    elif due_iso and today_iso == due_iso:
        out.append("Borçlarınız için son ödeme tarihiniz bugündür.")
    elif due:
        out.append("Borçlarınız için son ödeme tarihiniz " + tr_date(due) + date_sfx(due) + ".")
    return " ".join(notes + out), False
