TR_TENS = ["", "on", "yirmi", "otuz", "kırk", "elli", "altmış", "yetmiş", "seksen", "doksan"]
TR_MONTHS = ["", "Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"]
TR_DIG = ["sıfır", "bir", "iki", "üç", "dört", "beş", "altı", "yedi", "sekiz", "dokuz"]

def tr_under_1000(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else TR_ONES[h] + " ") + "yüz")
    if t:
        s.append(TR_TENS[t])
    if o:
        s.append(TR_ONES[o])
    return " ".join(s)

def tr_words(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for div, name in ((10**9, "milyar"), (10**6, "milyon"), (1000, "bin")):
        q, n = divmod(n, div)
        if q:
            if div == 1000 and q == 1:
                parts.append("bin")
            else:
                parts.append(tr_under_1000(q) + " " + name)
    if n:
        parts.append(tr_under_1000(n))
    return " ".join(parts)

def tr_money(x, cur):
    x = round(float(x) + 1e-9, 2)
    whole = int(x)
    frac = int(round((x - whole) * 100))
    unit = {"TL": "lira", "USD": "dolar", "EUR": "euro", "GBP": "sterlin"}[cur]
    sub = {"TL": "kuruş", "USD": "sent", "EUR": "sent", "GBP": "peni"}[cur]
    if cur == "TL" and not frac:
        return tr_words(whole) + " Türk Lirası"
    s = tr_words(whole) + " " + unit
    if frac:
        s += " " + tr_words(frac) + " " + sub
    return s

TR_SUF = {"Lirası": "'dır", "lira": "'dır", "kuruş": "'tur", "dolar": "'dır", "sent": "'tir", "euro": "'dur", "sterlin": "'dir", "peni": "'dir"}

def sfx(s):
    return s + TR_SUF.get(s.split(" ")[-1], "'dir")

def tr_date(s):
    try:
        d, m, y = [int(p) for p in str(s).split(".")]
        return "%d %s %d" % (d, TR_MONTHS[m], y)
    except Exception:
        return str(s)

def date_sfx(s):
    try:
        y = int(str(s).split(".")[2])
    except Exception:
        return "'dir"
    last = {1: "'dir", 2: "'dir", 3: "'tür", 4: "'tür", 5: "'tir", 6: "'dır", 7: "'dir", 8: "'dir", 9: "'dur"}
    if y % 10:
        return last[y % 10]
    return {1: "'dur", 2: "'dir", 3: "'dur", 4: "'tır", 5: "'dir", 6: "'tır", 7: "'tir", 8: "'dir", 9: "'dır", 0: "'dir"}[(y // 10) % 10]

def tr_iso(s):
    try:
        d, m, y = [int(p) for p in str(s).split(".")]
        return "%04d-%02d-%02d" % (y, m, d)
    except Exception:
        return ""

