def tr_under_1000(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(("" if h == 1 else TR_ONES[h] + " ") + "yüz")
    if t:
        s.append(TR_TENS[t])
    if o:
        s.append(TR_ONES[o])
    return " ".join(s)

def tr_words(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for div, name in ((10**9, "milyar"), (10**6, "milyon"), (1000, "bin")):
        q, n = divmod(n, div)
        if q:
            if div == 1000 and q == 1:
                parts.append("bin")
            else:
                parts.append(tr_under_1000(q) + " " + name)
    if n:
        parts.append(tr_under_1000(n))
    return " ".join(parts)

def tr_money(x, cur):
    x = round(float(x) + 1e-9, 2)
