        sd, mp, rd, rmp = (tr_num(tl.get(k)) for k in ("statementDebt", "minPayment", "remainingDebt", "remainingMinPayment"))
        transfers = [CUR_NAME[c] for c in ("USD", "EUR", "GBP") if isinstance(blocks.get(c), dict) and tr_num(blocks[c].get("transferAmount")) > 0]
        if rd <= 0:
