                out.append(lead + X + ", ödenmesi gereken minimum tutar " + sfx(Z) + ".")
            else:
                out.append(lead + X + ", ödenmesi gereken minimum tutar " + Z + ", kalan toplam borcunuz " + Y + ", kalan minimum ödeme tutarınız " + sfx(T) + ".")
    for c in ("USD", "EUR", "GBP"):
        blk = blocks.get(c)
        if not isinstance(blk, dict) or not blk:
            continue
        sd, mp, rd = (tr_num(blk.get(k)) for k in ("statementDebt", "minPayment", "remainingDebt"))
        if rd <= 0 and sd <= 0:
            clear.append(CUR_NAME[c])
            continue
        if rd <= 0:
            clear.append(CUR_NAME[c])
            continue
