            out.append("Toplam borcunuz " + sfx(tr_money(tlb.get("totalDebt"), "TL")) + ".")
    elif due_iso and today_iso == due_iso:
        out.append("Borçlarınız için son ödeme tarihiniz bugündür.")
    elif due:
        out.append("Borçlarınız için son ödeme tarihiniz " + tr_date(due) + date_sfx(due) + ".")
